 journal.panel=panel.gameObject;journal.heading=Text("Heading",panel,30,48);journal.body=Text("Entries",panel,23,300);journal.body.gameObject.GetComponent<UnityEngine.UI.LayoutElement>().flexibleHeight=1;journal.body.gameObject.GetComponent<UnityEngine.UI.LayoutElement>().minHeight=120;
