 var accept=Action("AcceptAdventure",quest,QuestDialogueCommand.Start);var clear=Action("ReportRaiders",quest,QuestDialogueCommand.TurnInStage,"clear-watch");var finish=Action("ReturnLedger",quest,QuestDialogueCommand.TurnInStage,"recover-ledger");
