 var inputPath="Assets/GamePlay/Character/InputSystem/mehh.inputactions";var input=InputActionAsset.FromJson(System.IO.File.ReadAllText(inputPath));try{var map=input.FindActionMap("Player",true);if(map.FindAction("Journal")==null){map.AddAction("Journal",InputActionType.Button).AddBinding("<Keyboard>/j",groups:"KeyboardMouse");System.IO.File.WriteAllText(inputPath,input.ToJson());AssetDatabase.ImportAsset(inputPath);}}finally{UnityEngine.Object.DestroyImmediate(input);}
