 var ledger=GameObject.CreatePrimitive(PrimitiveType.Cube);SceneManager.MoveGameObjectToScene(ledger,scene);ledger.name="LostLedgerPickup";ledger.transform.position=new Vector3(7,.4f,10);ledger.transform.localScale=new Vector3(.6f,.3f,.8f);ledger.AddComponent<ItemInteract>().item=relic;
